function speak(text,{id='',court='',force=false}={}){text=String(text||'').trim();court=court||S.selectedCourt;if(!text||!S.blv.enabled)return false;if(!force&&id&&S.blv.lastSpoken[court]===id)return false;if(id)S.blv.lastSpoken[court]=id;if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){blvStatus(ui('Thiết bị không có SpeechSynthesis.'),'err');return false}try{speechSynthesis.cancel();speechSynthesis.resume?.();const u=new SpeechSynthesisUtterance(text);u.lang='vi-VN';u.rate=1.06;u.pitch=.98;u.volume=1;const vo=viVoice();if(vo)u.voice=vo;u.onstart=()=>blvStatus('🔊 '+text.slice(0,105),'working');u.onend=()=>{S.blv.lastSpokenAt=Date.now();blvStatus(ui('✓ Đã phát BLV tỷ số'),'ok')};u.onerror=e=>blvStatus(ui('TTS Viewer lỗi: ')+(e?.error||'speech error'),'err');speechSynthesis.speak(u);return true}catch(e){blvStatus(ui('Không phát được BLV: ')+(e?.message||e),'err');return false}}
async function enableBlv(){S.blv.enabled=true;const v=$('tk109-video');if(v){v.muted=false;v.volume=1;v.play().catch(()=>{})}try{speechSynthesis.resume?.()}catch{}$('tk109-audio').textContent=ui('✓ Tiếng + BLV đã bật');bindCommentary(true);blvStatus(`✓ Audio Viewer ON · đang nghe BLV ${S.selectedCourt||'sân Live'}.`,'ok');speak('Âm thanh bình luận tỷ số đã bật.',{id:'u109-enable-'+Date.now(),court:S.selectedCourt,force:true})}
function commentKey(row,c){return String(row?.id||row?.createdAt||`${c}:${String(row?.text||'').trim()}`)}
function bindCommentary(force=false){const c=S.selectedCourt;if(!S.db||!c)return; if(!force&&S.blv.court===c&&S.blv.off)return;try{S.blv.off?.()}catch{}S.blv.court=c;const r=S.db.ref(path(`commentary/${c}/latest`));let first=true,fn=s=>{const row=s.val(),key=commentKey(row,c);if(!row?.text||!key)return;if(first){first=false;S.blv.lastSeen[c]=key;return}if(S.blv.lastSeen[c]===key)return;S.blv.lastSeen[c]=key;clearTimeout(S.blv.fallback);if(S.blv.enabled&&c===S.selectedCourt)speak(row.text,{id:key,court:c})};r.on('value',fn);S.blv.off=()=>r.off('value',fn)}
function scoreFallback(c,cur,prev){if(!S.blv.enabled||c!==S.selectedCourt||!cur?.matchId||!prev)return;const a=Number(cur.sets?.[cur.setIndex]?.a||0),b=Number(cur.sets?.[cur.setIndex]?.b||0),oa=Number(prev.sets?.[prev.setIndex]?.a||0),ob=Number(prev.sets?.[prev.setIndex]?.b||0);if(a===oa&&b===ob)return;const m=S.state.matches?.[cur.matchId]||{};let who='';if(a>oa&&b===ob)who=teamName(m.teamAId);else if(b>ob&&a===oa)who=teamName(m.teamBId);const text=who?`${who} ghi điểm, tỷ số ${a} - ${b}.`:`Tỷ số được cập nhật, ${teamName(m.teamAId)} ${a} - ${b} ${teamName(m.teamBId)}.`;clearTimeout(S.blv.fallback);S.blv.fallback=setTimeout(()=>speak(text,{id:`score:${c}:${cur.matchId}:${cur.setIndex}:${a}:${b}`,court:c}),700)}
function onActiveChange(c,cur,prev){scoreFallback(c,cur,prev);S.blv.lastScore[c]=cur?JSON.parse(JSON.stringify(cur)):cur;rafOnce('live',renderLive)}
function isPortrait(v=$('tk109-video')){return !!(v&&v.srcObject&&v.videoWidth>0&&v.videoHeight>v.videoWidth*1.08)}
function effectiveRotation(){return S.rotation==null?(isPortrait()?90:0):S.rotation}
function syncRotation(){const v=$('tk109-video'),p=$('tk109-player'),rot=effectiveRotation();if(!v||!p)return;p.classList.toggle('rot90',rot===90);p.classList.toggle('rotm90',rot===-90);p.classList.toggle('rot180',Math.abs(rot)===180);if(rot===90||rot===-90){const w=Math.max(1,p.clientWidth||innerWidth),h=Math.max(1,p.clientHeight||Math.round(w*9/16));v.style.setProperty('--rot-w',h+'px');v.style.setProperty('--rot-h',w+'px')}else{v.style.removeProperty('--rot-w');v.style.removeProperty('--rot-h')}$('tk109-rotate')?.classList.toggle('hidden',!v.srcObject)}
function bindVideo(){const v=$('tk109-video');if(!v||S.boundVideo===v)return;S.boundVideo=v;['loadedmetadata','resize','playing'].forEach(x=>v.addEventListener(x,syncRotation,{passive:true}));try{S.resizeObserver=new ResizeObserver(syncRotation);S.resizeObserver.observe($('tk109-player'))}catch{}}
function cycleRotation(){const r=effectiveRotation();S.rotation=r===90?-90:r===-90?0:r===0?90:0;syncRotation()}
async function toggleFullscreen(){const st=$('tk109-live-stage');if(!st)return;try{if(document.fullscreenElement===st)await document.exitFullscreen();else await st.requestFullscreen?.({navigationUI:'hide'})}catch{}syncRotation()}
function listenMap(name,onChange){const ref=S.db.ref(path(name)),map=S.state[name]||(S.state[name]={}),offs=[];for(const ev of ['child_added','child_changed']){const fn=s=>{const prev=map[s.key];map[s.key]=s.val();onChange?.(s.key,map[s.key],prev)};ref.on(ev,fn);offs.push(()=>ref.off(ev,fn))}const rm=s=>{const prev=map[s.key];delete map[s.key];onChange?.(s.key,null,prev)};ref.on('child_removed',rm);offs.push(()=>ref.off('child_removed',rm));return()=>offs.forEach(f=>f())}
const W={teamOff:new Map(),liveMatchOff:new Map(),scheduleLimit:60,pastLimit:20};
function mergeMatches(){S.state.matches={...S.state.standingMatches,...S.state.scheduleMatches,...S.state.liveMatches}}
function neededTeamIds(){const ids=new Set();for(const m of [...Object.values(S.state.scheduleMatches||{}),...Object.values(S.state.standingMatches||{}),...Object.values(S.state.liveMatches||{})]){if(m?.teamAId)ids.add(m.teamAId);if(m?.teamBId)ids.add(m.teamBId)}return ids}
function syncTeams(){const need=neededTeamIds();for(const [id,off] of W.teamOff){if(!need.has(id)){try{off()}catch{};W.teamOff.delete(id);delete S.state.teams[id]}}for(const id of need){if(W.teamOff.has(id))continue;const r=S.db.ref(path('teams/'+id)),fn=s=>{const v=s.val();if(v)S.state.teams[id]=v;else delete S.state.teams[id];rafOnce('schedule',renderSchedule);rafOnce('standing',renderStandings);rafOnce('live',renderLive)};r.on('value',fn);W.teamOff.set(id,()=>r.off('value',fn))}}
function rebuildData(){mergeMatches()}
function listenQueryMap(query,target,onChange){const map=S.state[target]||(S.state[target]={}),offs=[];for(const ev of ['child_added','child_changed']){const fn=s=>{const prev=map[s.key];map[s.key]=s.val();rebuildData();onChange?.(s.key,map[s.key],prev)};query.on(ev,fn);offs.push(()=>query.off(ev,fn))}const rm=s=>{const prev=map[s.key];delete map[s.key];rebuildData();onChange?.(s.key,null,prev)};query.on('child_removed',rm);offs.push(()=>query.off('child_removed',rm));return()=>offs.forEach(f=>f())}
function syncLiveMatchListeners(){const need=new Set(Object.values(S.state.activeMatches||{}).map(x=>x?.matchId).filter(Boolean));for(const [id,off] of W.liveMatchOff){if(!need.has(id)){try{off()}catch{};W.liveMatchOff.delete(id);delete S.state.liveMatches[id]}}for(const id of need){if(W.liveMatchOff.has(id))continue;const r=S.db.ref(path('matches/'+id)),fn=s=>{const v=s.val();if(v)S.state.liveMatches[id]=v;else delete S.state.liveMatches[id];rebuildData();rafOnce('live',renderLive);rafOnce('schedule',renderSchedule)};r.on('value',fn);W.liveMatchOff.set(id,()=>r.off('value',fn))}rebuildData()}
function dateShift(iso,days){const [y,m,d]=iso.split('-').map(Number),x=new Date(y,m-1,d);x.setDate(x.getDate()+days);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function subscribe(){S.offs.forEach(f=>{try{f()}catch{}});S.offs=[];for(const off of W.teamOff.values())try{off()}catch{};W.teamOff.clear();for(const off of W.liveMatchOff.values())try{off()}catch{};W.liveMatchOff.clear();S.state.scheduleMatches={};S.state.standingMatches={};S.state.liveMatches={};S.state.matches={};S.state.teams={};
 const cfg=S.db.ref(path('config'));const cf=s=>{S.state.config=s.val()||{rules:{}};refreshTitle();rafOnce('standing',renderStandings)};cfg.on('value',cf);S.offs.push(()=>cfg.off('value',cf));
 const today=localISO(),matchesRef=S.db.ref(path('matches'));
 const pastQ=matchesRef.orderByChild('date').endAt(today).limitToLast(W.pastLimit),futureQ=matchesRef.orderByChild('date').startAt(today).limitToFirst(W.scheduleLimit);
 const scheduleChanged=()=>{rafOnce('schedule',renderSchedule);rafOnce('live',renderLive)};S.offs.push(listenQueryMap(pastQ,'scheduleMatches',scheduleChanged));S.offs.push(listenQueryMap(futureQ,'scheduleMatches',scheduleChanged));
 for(const st of ['FINISHED','WALKOVER','RETIRED','DISQUALIFIED']){const q=matchesRef.orderByChild('status').equalTo(st);S.offs.push(listenQueryMap(q,'standingMatches',()=>{rafOnce('standing',renderStandings);rafOnce('schedule',renderSchedule)}))}
 S.offs.push(listenMap('teams',()=>{rafOnce('schedule',renderSchedule);rafOnce('standing',renderStandings);rafOnce('live',renderLive)}));
 S.offs.push(listenMap('courts',()=>{rafOnce('schedule',renderSchedule);rafOnce('live',renderLive)}));
 S.offs.push(listenMap('activeMatches',(k,cur,prev)=>{onActiveChange(k,cur,prev);syncLiveMatchListeners()}));
 const annQ=S.db.ref(path('announcements')).orderByChild('createdAt').limitToLast(1),annFn=s=>{S.state.announcements={};if(s.exists())s.forEach(c=>S.state.announcements[c.key]=c.val());renderAnnouncement()};annQ.on('value',annFn);S.offs.push(()=>annQ.off('value',annFn));
 renderSchedule();renderStandings();renderLive();renderAnnouncement()}

async function waitFirebase(timeout=12000){const start=Date.now();while(Date.now()-start<timeout){if(window.firebase?.initializeApp&&window.firebase?.database)return true;await new Promise(r=>setTimeout(r,40))}throw new Error('Firebase Database tải quá chậm hoặc bị chặn')}
